package main

import (
	"bufio"
	"fmt"
	"os"
)

type Fibonacci struct {
	mod        int64
	calculated map[int64]int64
}

func NewFibonacci(mod int64) *Fibonacci {
	return &Fibonacci{
		mod: mod,
		calculated: map[int64]int64{
			0: 1,
			1: 1,
		},
	}
}

func (f *Fibonacci) Fib(n int64) int64 {
	if value, ok := f.calculated[n]; ok {
		return value
	}

	k := n / 2
	var result int64

	if n%2 == 0 {
		result = (f.Fib(k)*f.Fib(k) + f.Fib(k-1)*f.Fib(k-1)) % f.mod
	} else {
		result = (f.Fib(k)*f.Fib(k+1) + f.Fib(k-1)*f.Fib(k)) % f.mod
	}

	f.calculated[n] = result
	return result
}

func exponentiation(a, b, mod int64) int64 {
	if b == 0 {
		return 1
	}
	if b == 1 {
		return a
	}
	if b%2 == 0 {
		return exponentiation(a*a%mod, b/2, mod)
	}
	return a * exponentiation(a*a%mod, (b-1)/2, mod) % mod
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 32768)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var n, k, l, mod int64
	fmt.Fscan(in, &n, &k, &l, &mod)

	if l != 64 {
		limit := int64(uint64(1) << uint(l))
		if limit-1 < k {
			fmt.Fprintln(out, 0)
			return
		}
	}

	zeroPos := NewFibonacci(mod).Fib(n + 1)
	onePos := exponentiation(2, n, mod) - zeroPos
	for onePos < 0 {
		onePos += mod
	}

	var result int64 = 1
	for i := int64(0); i < l; i++ {
		bit := int64(uint64(1) << uint(i))
		if k&bit != 0 {
			result *= onePos
		} else {
			result *= zeroPos
		}
		result %= mod
	}

	fmt.Fprintln(out, result%mod)
}

